    <link rel="stylesheet" href="https://api.fontshare.com/v2/css?f[]=clash-display@400,500,600,700&f[]=satoshi@300,400,500,700&display=swap">

    <style>
        /* ===========================================
           CSS CUSTOM PROPERTIES (NEON CYBER THEME)
           Inspired by deep-sea terminal aesthetics
           =========================================== */
        :root {
            --bg-primary: #070d1a;
            --bg-secondary: #0d1628;
            --bg-card: rgba(13, 22, 40, 0.85);
            --text-primary: #e8f4ff;
            --text-secondary: #7ea8c9;
            --accent-cyan: #00e5ff;
            --accent-cyan-dim: rgba(0, 229, 255, 0.15);
            --accent-cyan-glow: rgba(0, 229, 255, 0.4);
            --accent-gold: #ffd060;
            --accent-gold-dim: rgba(255, 208, 96, 0.15);
            --accent-red: #ff4060;
            --accent-green: #00ff8c;
            --accent-green-dim: rgba(0, 255, 140, 0.12);
            --border-subtle: rgba(0, 229, 255, 0.12);
            --border-strong: rgba(0, 229, 255, 0.35);

            /* Typography — MUST use clamp() */
            --font-display: 'Clash Display', sans-serif;
            --font-body: 'Satoshi', sans-serif;
            --title-size: clamp(1.8rem, 5.5vw, 4.5rem);
            --h2-size: clamp(1.3rem, 3.2vw, 2.4rem);
            --h3-size: clamp(1rem, 2.2vw, 1.6rem);
            --body-size: clamp(0.75rem, 1.3vw, 1.05rem);
            --small-size: clamp(0.65rem, 1vw, 0.875rem);
            --micro-size: clamp(0.6rem, 0.85vw, 0.8rem);

            /* Spacing */
            --slide-padding: clamp(1.5rem, 4vw, 4.5rem);
            --content-gap: clamp(0.6rem, 1.8vw, 2rem);
            --element-gap: clamp(0.3rem, 0.8vw, 0.8rem);

            /* Animation */
            --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
            --duration-fast: 0.4s;
            --duration-normal: 0.65s;
            --duration-slow: 1s;
        }

        /* ===========================================
           BASE RESET
           =========================================== */
        *, *::before, *::after {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: var(--font-body);
            background: var(--bg-primary);
            color: var(--text-primary);
            -webkit-font-smoothing: antialiased;
        }

        /* ===========================================
           VIEWPORT-BASE.CSS — MANDATORY INCLUSION
           =========================================== */
        html, body {
            height: 100%;
            overflow-x: hidden;
        }

        html {
            scroll-snap-type: y mandatory;
            scroll-behavior: smooth;
        }

        .slide {
            width: 100vw;
            height: 100vh;
            height: 100dvh;
            overflow: hidden;
            scroll-snap-align: start;
            display: flex;
            flex-direction: column;
            position: relative;
        }

        .slide-content {
            flex: 1;
            display: flex;
            flex-direction: column;
            justify-content: center;
            max-height: 100%;
            overflow: hidden;
            padding: var(--slide-padding);
        }

        .card, .container, .content-box {
            max-width: min(90vw, 1000px);
            max-height: min(80vh, 700px);
        }

        .feature-list, .bullet-list {
            gap: clamp(0.4rem, 1vh, 1rem);
        }

        .feature-list li, .bullet-list li {
            font-size: var(--body-size);
            line-height: 1.4;
        }

        .grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(min(100%, 250px), 1fr));
            gap: clamp(0.5rem, 1.5vw, 1rem);
        }

        img, .image-container {
            max-width: 100%;
            max-height: min(50vh, 400px);
            object-fit: contain;
        }

        /* Short viewports */
        @media (max-height: 700px) {
            :root {
                --slide-padding: clamp(0.75rem, 3vw, 2rem);
                --content-gap: clamp(0.4rem, 1.5vw, 1rem);
                --title-size: clamp(1.25rem, 4.5vw, 2.5rem);
                --h2-size: clamp(1rem, 3vw, 1.75rem);
            }
        }

        @media (max-height: 600px) {
            :root {
                --slide-padding: clamp(0.5rem, 2.5vw, 1.5rem);
                --content-gap: clamp(0.3rem, 1vw, 0.75rem);
                --title-size: clamp(1.1rem, 4vw, 2rem);
                --body-size: clamp(0.7rem, 1.2vw, 0.95rem);
            }
            .nav-dots, .keyboard-hint, .decorative { display: none; }
        }

        @media (max-height: 500px) {
            :root {
                --slide-padding: clamp(0.4rem, 2vw, 1rem);
                --title-size: clamp(1rem, 3.5vw, 1.5rem);
                --h2-size: clamp(0.9rem, 2.5vw, 1.25rem);
                --body-size: clamp(0.65rem, 1vw, 0.85rem);
            }
        }

        @media (max-width: 600px) {
            :root { --title-size: clamp(1.25rem, 7vw, 2.5rem); }
            .grid { grid-template-columns: 1fr; }
        }

        @media (prefers-reduced-motion: reduce) {
            *, *::before, *::after {
                animation-duration: 0.01ms !important;
                transition-duration: 0.2s !important;
            }
            html { scroll-behavior: auto; }
        }

        /* ===========================================
           GLOBAL BACKGROUNDS & ATMOSPHERE
           Grid + gradient mesh for depth
           =========================================== */
        .slide-bg {
            position: absolute;
            inset: 0;
            z-index: 0;
            background: var(--bg-primary);
        }

        /* Grid pattern overlay */
        .slide-bg::before {
            content: '';
            position: absolute;
            inset: 0;
            background-image:
                linear-gradient(rgba(0, 229, 255, 0.04) 1px, transparent 1px),
                linear-gradient(90deg, rgba(0, 229, 255, 0.04) 1px, transparent 1px);
            background-size: 48px 48px;
        }

        /* Radial glow from bottom-left corner */
        .slide-bg::after {
            content: '';
            position: absolute;
            inset: 0;
            background:
                radial-gradient(ellipse at 15% 90%, rgba(0, 229, 255, 0.08) 0%, transparent 55%),
                radial-gradient(ellipse at 90% 10%, rgba(255, 208, 96, 0.05) 0%, transparent 45%);
        }

        .slide > * { position: relative; z-index: 1; }

        /* ===========================================
           ANIMATIONS — REVEAL SYSTEM
           Staggered fade+slide-up on .visible
           =========================================== */
        .reveal {
            opacity: 0;
            transform: translateY(24px);
            transition:
                opacity var(--duration-normal) var(--ease-out-expo),
                transform var(--duration-normal) var(--ease-out-expo);
        }

        .slide.visible .reveal { opacity: 1; transform: translateY(0); }
        .slide.visible .reveal:nth-child(1) { transition-delay: 0.05s; }
        .slide.visible .reveal:nth-child(2) { transition-delay: 0.15s; }
        .slide.visible .reveal:nth-child(3) { transition-delay: 0.25s; }
        .slide.visible .reveal:nth-child(4) { transition-delay: 0.35s; }
        .slide.visible .reveal:nth-child(5) { transition-delay: 0.42s; }
        .slide.visible .reveal:nth-child(6) { transition-delay: 0.49s; }
        .slide.visible .reveal:nth-child(7) { transition-delay: 0.56s; }

        .reveal-left {
            opacity: 0;
            transform: translateX(-32px);
            transition:
                opacity var(--duration-normal) var(--ease-out-expo),
                transform var(--duration-normal) var(--ease-out-expo);
        }
        .slide.visible .reveal-left { opacity: 1; transform: translateX(0); }
        .slide.visible .reveal-left:nth-child(1) { transition-delay: 0.1s; }
        .slide.visible .reveal-left:nth-child(2) { transition-delay: 0.2s; }
        .slide.visible .reveal-left:nth-child(3) { transition-delay: 0.3s; }
        .slide.visible .reveal-left:nth-child(4) { transition-delay: 0.4s; }
        .slide.visible .reveal-left:nth-child(5) { transition-delay: 0.5s; }

        /* ===========================================
           PROGRESS BAR
           =========================================== */
        .progress-bar {
            position: fixed;
            top: 0;
            left: 0;
            height: 2px;
            background: linear-gradient(90deg, var(--accent-cyan), var(--accent-gold));
            z-index: 1000;
            transition: width 0.3s ease;
            box-shadow: 0 0 8px var(--accent-cyan-glow);
        }

        /* ===========================================
           NAV DOTS
           =========================================== */
        .nav-dots {
            position: fixed;
            right: clamp(1rem, 2vw, 2rem);
            top: 50%;
            transform: translateY(-50%);
            display: flex;
            flex-direction: column;
            gap: clamp(6px, 0.8vh, 10px);
            z-index: 1000;
        }

        .nav-dot {
            width: 6px;
            height: 6px;
            border-radius: 50%;
            background: rgba(0, 229, 255, 0.3);
            cursor: pointer;
            transition: all 0.3s ease;
            border: none;
            padding: 0;
        }

        .nav-dot.active {
            background: var(--accent-cyan);
            box-shadow: 0 0 8px var(--accent-cyan-glow);
            transform: scale(1.4);
        }

        /* ===========================================
           SLIDE NUMBER BADGE
           =========================================== */
        .slide-num {
            position: absolute;
            top: var(--slide-padding);
            right: var(--slide-padding);
            font-family: var(--font-display);
            font-size: var(--small-size);
            color: rgba(0, 229, 255, 0.4);
            letter-spacing: 0.1em;
            font-weight: 500;
        }

        /* ===========================================
           TYPOGRAPHY SYSTEM
           =========================================== */
        h1 {
            font-family: var(--font-display);
            font-size: var(--title-size);
            font-weight: 700;
            line-height: 1.05;
            letter-spacing: -0.02em;
        }

        h2 {
            font-family: var(--font-display);
            font-size: var(--h2-size);
            font-weight: 600;
            line-height: 1.15;
            letter-spacing: -0.01em;
        }

        h3 {
            font-family: var(--font-display);
            font-size: var(--h3-size);
            font-weight: 500;
        }

        .label {
            font-family: var(--font-body);
            font-size: var(--micro-size);
            font-weight: 500;
            text-transform: uppercase;
            letter-spacing: 0.18em;
            color: var(--accent-cyan);
        }

        .cyan { color: var(--accent-cyan); }
        .gold { color: var(--accent-gold); }
        .red { color: var(--accent-red); }
        .green { color: var(--accent-green); }
        .dim { color: var(--text-secondary); }

        /* Glowing accent line */
        .accent-line {
            width: clamp(32px, 4vw, 64px);
            height: 2px;
            background: linear-gradient(90deg, var(--accent-cyan), transparent);
            box-shadow: 0 0 6px var(--accent-cyan-glow);
        }

        /* ===========================================
           STAT CARD COMPONENT
           =========================================== */
        .stat-card {
            background: var(--bg-card);
            border: 1px solid var(--border-subtle);
            border-radius: 8px;
            padding: clamp(0.8rem, 1.5vw, 1.4rem);
            display: flex;
            flex-direction: column;
            gap: clamp(0.2rem, 0.5vw, 0.5rem);
            transition: border-color 0.3s ease;
        }

        .stat-card:hover {
            border-color: var(--border-strong);
        }

        .stat-card .stat-value {
            font-family: var(--font-display);
            font-size: clamp(1.1rem, 2.8vw, 2.2rem);
            font-weight: 700;
            color: var(--accent-cyan);
            line-height: 1;
        }

        .stat-card .stat-label {
            font-size: var(--small-size);
            color: var(--text-secondary);
            font-weight: 400;
        }

        /* ===========================================
           BAR CHART COMPONENT
           =========================================== */
        .bar-chart {
            display: flex;
            flex-direction: column;
            gap: clamp(0.3rem, 0.7vw, 0.7rem);
            width: 100%;
        }

        .bar-row {
            display: grid;
            grid-template-columns: clamp(90px, 18%, 160px) 1fr clamp(50px, 8%, 80px);
            align-items: center;
            gap: clamp(0.4rem, 0.8vw, 0.8rem);
        }

        .bar-label {
            font-size: var(--small-size);
            color: var(--text-secondary);
            text-align: right;
            font-weight: 400;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
        }

        .bar-track {
            background: rgba(255,255,255,0.05);
            border-radius: 3px;
            height: clamp(10px, 1.5vh, 18px);
            overflow: hidden;
        }

        .bar-fill {
            height: 100%;
            border-radius: 3px;
            width: 0;
            transition: width 1s var(--ease-out-expo);
        }

        .slide.visible .bar-fill { width: var(--bar-width); }

        .bar-val {
            font-family: var(--font-display);
            font-size: var(--small-size);
            font-weight: 600;
            color: var(--text-primary);
            white-space: nowrap;
        }

        /* ===========================================
           SVG CHARTS (inline)
           =========================================== */
        .chart-wrapper {
            width: 100%;
            overflow: hidden;
        }

        .chart-wrapper svg {
            width: 100%;
            height: auto;
            max-height: min(45vh, 340px);
        }

        /* ===========================================
           SLIDE 1: TITLE SLIDE
           =========================================== */
        .title-slide .slide-bg::after {
            background:
                radial-gradient(ellipse at 50% 100%, rgba(0, 229, 255, 0.12) 0%, transparent 60%),
                radial-gradient(ellipse at 80% 20%, rgba(255, 208, 96, 0.07) 0%, transparent 45%);
        }

        .title-slide .title-content {
            display: flex;
            flex-direction: column;
            justify-content: center;
            height: 100%;
            padding: var(--slide-padding);
            max-width: min(88vw, 1100px);
            margin: 0 auto;
            width: 100%;
        }

        .title-slide h1 {
            background: linear-gradient(135deg, var(--text-primary) 0%, var(--accent-cyan) 60%, var(--accent-gold) 100%);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
            margin-bottom: clamp(0.5rem, 1.2vw, 1.2rem);
        }

        .title-slide .subtitle {
            font-size: clamp(0.85rem, 1.8vw, 1.3rem);
            color: var(--text-secondary);
            font-weight: 400;
            max-width: 55ch;
            line-height: 1.5;
            margin-bottom: clamp(1.2rem, 2.5vw, 2.5rem);
        }

        .title-kpis {
            display: flex;
            gap: clamp(1rem, 2.5vw, 3rem);
            flex-wrap: wrap;
            margin-top: clamp(0.5rem, 1vw, 1rem);
        }

        .title-kpi {
            display: flex;
            flex-direction: column;
            gap: 2px;
        }

        .title-kpi .kv {
            font-family: var(--font-display);
            font-size: clamp(1.1rem, 2.4vw, 1.9rem);
            font-weight: 700;
            color: var(--accent-cyan);
        }

        .title-kpi .kl {
            font-size: var(--micro-size);
            color: var(--text-secondary);
            text-transform: uppercase;
            letter-spacing: 0.12em;
        }

        .title-badge {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            padding: clamp(4px, 0.6vw, 8px) clamp(8px, 1.2vw, 14px);
            background: var(--accent-cyan-dim);
            border: 1px solid var(--border-strong);
            border-radius: 100px;
            margin-bottom: clamp(0.8rem, 1.5vw, 1.8rem);
        }

        .title-badge .dot {
            width: 7px;
            height: 7px;
            border-radius: 50%;
            background: var(--accent-cyan);
            box-shadow: 0 0 6px var(--accent-cyan);
            animation: pulse-dot 2s ease-in-out infinite;
        }

        @keyframes pulse-dot {
            0%, 100% { opacity: 1; transform: scale(1); }
            50% { opacity: 0.5; transform: scale(0.8); }
        }

        .title-badge span {
            font-size: var(--micro-size);
            font-weight: 500;
            color: var(--accent-cyan);
            letter-spacing: 0.08em;
        }

        /* ===========================================
           SLIDE 2: SUPPLY CHANGE SNAPSHOT
           Waterfall/bar chart issuance vs burn
           =========================================== */
        .waterfall-container {
            display: flex;
            align-items: flex-end;
            gap: clamp(0.8rem, 2vw, 2.5rem);
            height: clamp(120px, 28vh, 220px);
            padding: 0 clamp(0.5rem, 2vw, 2rem);
        }

        .wf-bar-group {
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: clamp(4px, 0.6vw, 8px);
            flex: 1;
        }

        .wf-bar-label {
            font-size: var(--small-size);
            color: var(--text-secondary);
            text-align: center;
        }

        .wf-bar-wrap {
            width: 100%;
            display: flex;
            align-items: flex-end;
            justify-content: center;
        }

        .wf-bar {
            width: clamp(36px, 6vw, 80px);
            border-radius: 4px 4px 0 0;
            position: relative;
        }

        .wf-bar .wf-val {
            position: absolute;
            top: calc(-1 * clamp(16px, 2vh, 24px));
            left: 50%;
            transform: translateX(-50%);
            font-family: var(--font-display);
            font-size: var(--small-size);
            font-weight: 700;
            white-space: nowrap;
        }

        /* Offset ratio badge */
        .offset-badge {
            display: inline-flex;
            align-items: center;
            background: rgba(255, 64, 96, 0.15);
            border: 1px solid rgba(255, 64, 96, 0.4);
            border-radius: 6px;
            padding: clamp(4px, 0.5vw, 8px) clamp(8px, 1vw, 14px);
            gap: clamp(4px, 0.5vw, 8px);
        }

        .two-col {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: clamp(0.8rem, 2vw, 2.5rem);
            align-items: start;
        }

        /* ===========================================
           SLIDE 3: GAS & BURN MECHANICS
           Gauge / range visualization
           =========================================== */
        .gas-gauge-track {
            width: 100%;
            height: clamp(10px, 1.5vh, 16px);
            background: rgba(255,255,255,0.06);
            border-radius: 100px;
            position: relative;
            overflow: visible;
            margin: clamp(0.4rem, 0.8vw, 0.8rem) 0;
        }

        .gas-gauge-fill {
            height: 100%;
            border-radius: 100px;
            background: linear-gradient(90deg, var(--accent-green), var(--accent-cyan), var(--accent-gold), var(--accent-red));
        }

        .gas-marker {
            position: absolute;
            top: 50%;
            transform: translateY(-50%);
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 2px;
        }

        .gas-marker-line {
            width: 2px;
            height: clamp(16px, 2.5vh, 28px);
            background: var(--text-primary);
            box-shadow: 0 0 4px rgba(255,255,255,0.6);
        }

        .gas-marker-label {
            font-family: var(--font-display);
            font-size: var(--micro-size);
            font-weight: 600;
            white-space: nowrap;
            color: var(--text-primary);
        }

        .gas-range-labels {
            display: flex;
            justify-content: space-between;
            font-size: var(--micro-size);
            color: var(--text-secondary);
        }

        .info-card {
            background: var(--bg-card);
            border: 1px solid var(--border-subtle);
            border-radius: 8px;
            padding: clamp(0.6rem, 1.2vw, 1.2rem);
        }

        /* ===========================================
           SLIDE 4: BURN LEADERBOARD / CATEGORIES
           Horizontal bar chart
           =========================================== */

        /* ===========================================
           SLIDE 5: STAKING ECONOMICS
           Donut chart via SVG + stats
           =========================================== */

        /* ===========================================
           SLIDE 6: SUPPLY PROJECTIONS
           SVG line chart
           =========================================== */

        /* ===========================================
           SLIDE 7: FLIPPENING & TVS
           Donut/pie chart + comparison bars
           =========================================== */
        .flippening-bars {
            display: flex;
            flex-direction: column;
            gap: clamp(0.4rem, 0.8vw, 0.8rem);
        }

        .flip-row {
            display: grid;
            grid-template-columns: clamp(50px, 10%, 90px) 1fr clamp(50px, 9%, 80px);
            align-items: center;
            gap: clamp(0.5rem, 1vw, 1rem);
        }

        .flip-label {
            font-size: var(--small-size);
            color: var(--text-secondary);
            text-align: right;
        }

        .flip-track {
            background: rgba(255,255,255,0.05);
            border-radius: 4px;
            height: clamp(12px, 1.8vh, 20px);
            overflow: hidden;
        }

        .flip-fill {
            height: 100%;
            border-radius: 4px;
            width: 0;
            transition: width 1.2s var(--ease-out-expo);
        }

        .slide.visible .flip-fill { width: var(--flip-width); }

        .flip-pct {
            font-family: var(--font-display);
            font-size: var(--small-size);
            font-weight: 700;
        }

        /* ===========================================
           SLIDE 8: KEY TAKEAWAYS
           =========================================== */
        .takeaway-list {
            display: flex;
            flex-direction: column;
            gap: clamp(0.35rem, 0.9vw, 1rem);
        }

        .takeaway-item {
            display: flex;
            align-items: flex-start;
            gap: clamp(0.5rem, 1vw, 1.2rem);
            padding: clamp(0.5rem, 1vw, 1rem) clamp(0.6rem, 1.2vw, 1.2rem);
            background: var(--bg-card);
            border: 1px solid var(--border-subtle);
            border-left: 3px solid var(--accent-cyan);
            border-radius: 0 8px 8px 0;
            opacity: 0;
            transform: translateX(-20px);
            transition:
                opacity var(--duration-normal) var(--ease-out-expo),
                transform var(--duration-normal) var(--ease-out-expo),
                border-color 0.3s ease;
        }

        .slide.visible .takeaway-item {
            opacity: 1;
            transform: translateX(0);
        }

        .takeaway-item:nth-child(1) { transition-delay: 0.1s; }
        .takeaway-item:nth-child(2) { transition-delay: 0.22s; }
        .takeaway-item:nth-child(3) { transition-delay: 0.34s; }
        .takeaway-item:nth-child(4) { transition-delay: 0.46s; }
        .takeaway-item:nth-child(5) { transition-delay: 0.58s; }

        .takeaway-item:hover { border-left-color: var(--accent-gold); }

        .takeaway-num {
            font-family: var(--font-display);
            font-size: clamp(0.75rem, 1.4vw, 1.1rem);
            font-weight: 700;
            color: var(--accent-cyan);
            opacity: 0.6;
            min-width: 1.5em;
            line-height: 1.5;
        }

        .takeaway-text {
            font-size: var(--body-size);
            line-height: 1.45;
            color: var(--text-primary);
        }

        .takeaway-text strong {
            color: var(--accent-gold);
            font-weight: 600;
        }

        /* ===========================================
           SECTION DIVIDER LINE
           =========================================== */
        .divider {
            width: 100%;
            height: 1px;
            background: var(--border-subtle);
            margin: clamp(0.4rem, 0.8vw, 0.8rem) 0;
        }

        /* ===========================================
           STATS ROW
           =========================================== */
        .stats-row {
            display: flex;
            gap: clamp(0.6rem, 1.5vw, 2rem);
            flex-wrap: wrap;
        }

        .mini-stat {
            display: flex;
            flex-direction: column;
            gap: 2px;
        }

        .mini-stat .mv {
            font-family: var(--font-display);
            font-size: clamp(0.95rem, 2.2vw, 1.75rem);
            font-weight: 700;
            line-height: 1;
        }

        .mini-stat .ml {
            font-size: var(--micro-size);
            color: var(--text-secondary);
            text-transform: uppercase;
            letter-spacing: 0.1em;
        }
    </style>
</head>
<body>

    <!-- ============================================================
