            <div class="two-col reveal" style="margin-top: clamp(0.4rem, 0.8vw, 0.8rem);">
                <!-- Left: Waterfall visual -->
                <div>
                    <div style="font-size: var(--small-size); color: var(--text-secondary); margin-bottom: clamp(0.5rem, 1vw, 1rem);">
                        Issuance vs. Burn — 7-Day (ETH)
                    </div>
                    <!-- SVG waterfall chart -->
                    <div class="chart-wrapper">
                        <svg viewBox="0 0 400 200" fill="none" xmlns="http://www.w3.org/2000/svg" style="max-height: min(30vh, 200px);">
                            <!-- Grid lines -->
                            <line x1="60" y1="10" x2="60" y2="170" stroke="rgba(0,229,255,0.1)" stroke-width="1"/>
                            <line x1="60" y1="170" x2="390" y2="170" stroke="rgba(0,229,255,0.15)" stroke-width="1"/>
                            <line x1="60" y1="130" x2="390" y2="130" stroke="rgba(255,255,255,0.05)" stroke-width="1" stroke-dasharray="4,4"/>
                            <line x1="60" y1="90" x2="390" y2="90" stroke="rgba(255,255,255,0.05)" stroke-width="1" stroke-dasharray="4,4"/>
