                            <text x="55" y="174" text-anchor="end" font-size="10" fill="rgba(126,168,201,0.7)" font-family="Satoshi, sans-serif">0</text>
                            <text x="55" y="134" text-anchor="end" font-size="10" fill="rgba(126,168,201,0.7)" font-family="Satoshi, sans-serif">5K</text>
                            <text x="55" y="94" text-anchor="end" font-size="10" fill="rgba(126,168,201,0.7)" font-family="Satoshi, sans-serif">10K</text>
                            <text x="55" y="54" text-anchor="end" font-size="10" fill="rgba(126,168,201,0.7)" font-family="Satoshi, sans-serif">15K</text>

                            <!-- ISSUANCE bar: 19,638 ETH ~= full height ~155px, starts at y=15 -->
                            <rect x="100" y="16" width="80" height="154" rx="4" fill="rgba(255,64,96,0.7)" stroke="rgba(255,64,96,0.9)" stroke-width="1.5">
                                <animate attributeName="height" from="0" to="154" dur="1s" begin="0.5s" fill="freeze"/>
                                <animate attributeName="y" from="170" to="16" dur="1s" begin="0.5s" fill="freeze"/>
                            </rect>

                            <!-- BURN bar: 192 ETH ~= 1.5px tall, shown as 2px with glow for visibility -->
                            <!-- Scale: ~1.53px per 192 ETH against 19,638 reference = ~2px, make it visible at 4px minimum -->
                            <rect x="220" y="168" width="80" height="2" rx="1" fill="rgba(0,229,255,0.9)" stroke="rgba(0,229,255,1)" stroke-width="1">
                                <animate attributeName="height" from="0" to="2" dur="0.6s" begin="1.2s" fill="freeze"/>
                            </rect>
                            <!-- Glow effect for burn bar -->
                            <rect x="218" y="166" width="84" height="6" rx="2" fill="none" stroke="rgba(0,229,255,0.4)" stroke-width="1"/>

                            <!-- NET bar: +19,446 ~= 153px -->
                            <rect x="325" y="17" width="60" height="153" rx="4" fill="rgba(255,208,96,0.25)" stroke="rgba(255,208,96,0.6)" stroke-width="1.5" stroke-dasharray="5,3">
                                <animate attributeName="height" from="0" to="153" dur="1s" begin="1.5s" fill="freeze"/>
                                <animate attributeName="y" from="170" to="17" dur="1s" begin="1.5s" fill="freeze"/>
                            </rect>

                            <!-- Bar value labels -->
                            <text x="140" y="12" text-anchor="middle" font-size="11" fill="rgba(255,100,120,1)" font-family="Clash Display, sans-serif" font-weight="700">+19,638</text>
                            <text x="260" y="159" text-anchor="middle" font-size="10" fill="rgba(0,229,255,1)" font-family="Clash Display, sans-serif" font-weight="700">-192</text>
                            <text x="355" y="13" text-anchor="middle" font-size="11" fill="rgba(255,208,96,0.9)" font-family="Clash Display, sans-serif" font-weight="700">+19,446</text>

                            <!-- X-axis labels -->
                            <text x="140" y="186" text-anchor="middle" font-size="10" fill="rgba(126,168,201,0.8)" font-family="Satoshi, sans-serif">Issuance</text>
