            <!-- Three info cards in a row -->
            <div style="display: grid; grid-template-columns: repeat(3, 1fr); gap: clamp(0.5rem, 1vw, 1rem);" class="reveal">
                <div class="info-card">
                    <div class="label" style="margin-bottom: 4px;">Current</div>
                    <div style="font-family: var(--font-display); font-size: clamp(1rem, 2.5vw, 1.8rem); font-weight: 700; color: var(--accent-cyan);">0.1 Gwei</div>
                    <div style="font-size: var(--small-size); color: var(--text-secondary);">7-day average base fee</div>
                </div>
                <div class="info-card">
