                let touchStartY = 0;
                let touchStartX = 0;

                document.addEventListener('touchstart', (e) => {
                    touchStartY = e.touches[0].clientY;
                    touchStartX = e.touches[0].clientX;
                }, { passive: true });

                document.addEventListener('touchend', (e) => {
                    const deltaY = touchStartY - e.changedTouches[0].clientY;
                    const deltaX = touchStartX - e.changedTouches[0].clientX;

                    if (Math.abs(deltaY) > Math.abs(deltaX) && Math.abs(deltaY) > 50) {
                        if (deltaY > 0) {
                            this.goToSlide(Math.min(this.currentSlide + 1, this.totalSlides - 1));
                        } else {
                            this.goToSlide(Math.max(this.currentSlide - 1, 0));
                        }
                    }
                }, { passive: true });
            }

            /* === MOUSE WHEEL NAVIGATION === */
            setupWheelNav() {
                let lastWheel = 0;
                document.addEventListener('wheel', (e) => {
                    const now = Date.now();
                    if (now - lastWheel < 800) return; // debounce
                    lastWheel = now;

                    if (e.deltaY > 0) {
                        this.goToSlide(Math.min(this.currentSlide + 1, this.totalSlides - 1));
                    } else {
                        this.goToSlide(Math.max(this.currentSlide - 1, 0));
                    }
                }, { passive: true });
            }

            /* === NAV DOTS ===
               Generated dynamically, clickable for direct navigation */
            setupNavDots() {
                const nav = document.getElementById('navDots');
                this.slides.forEach((slide, i) => {
                    const dot = document.createElement('button');
                    dot.className = 'nav-dot' + (i === 0 ? ' active' : '');
                    dot.setAttribute('aria-label', `Go to slide ${i + 1}`);
                    dot.addEventListener('click', () => this.goToSlide(i));
                    nav.appendChild(dot);
                });
            }

            updateNavDots(activeIdx) {
                document.querySelectorAll('.nav-dot').forEach((dot, i) => {
                    dot.classList.toggle('active', i === activeIdx);
                });
            }

            /* === PROGRESS BAR === */
            updateProgress(slideIdx) {
                const pct = this.totalSlides > 1
                    ? (slideIdx / (this.totalSlides - 1)) * 100
                    : 100;
                document.getElementById('progressBar').style.width = pct + '%';
            }

            /* === SLIDE NAVIGATION ===
               Scrolls to a specific slide index */
            goToSlide(idx) {
                if (idx < 0 || idx >= this.totalSlides) return;
                this.slides[idx].scrollIntoView({ behavior: 'smooth', block: 'start' });
                this.currentSlide = idx;
                this.updateProgress(idx);
                this.updateNavDots(idx);
            }
        }

        // Boot when DOM is ready
        document.addEventListener('DOMContentLoaded', () => {
            new SlidePresentation();
        });
    </script>
</body>
</html>
