const { chromium } = require('playwright');
const http = require('http');
const fs = require('fs');
const path = require('path');

(async () => {
    const htmlPath = process.argv[2];
    const outDir = process.argv[3];
    const htmlDir = path.dirname(htmlPath);
    const htmlFile = path.basename(htmlPath);

    // Serve HTML directory via local HTTP
    const server = http.createServer((req, res) => {
        const filePath = path.join(htmlDir, decodeURIComponent(req.url.split('?')[0]));
        try {
            const data = fs.readFileSync(filePath);
            res.writeHead(200);
            res.end(data);
        } catch {
            res.writeHead(404);
            res.end('Not found');
        }
    });

    await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
    const port = server.address().port;
    const url = `http://127.0.0.1:${port}/${htmlFile}`;

    const browser = await chromium.launch({ executablePath: process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH || undefined });
    const page = await browser.newPage();
    await page.setViewportSize({ width: 1920, height: 1080 });
    await page.goto(url, { waitUntil: 'networkidle' });

    // Wait for initial animations
    await page.waitForTimeout(800);

    // Capture each slide by scrolling it into view
    const slideCount = await page.$$eval('.slide', els => els.length);
    console.error(`Found ${slideCount} slides`);

    for (let i = 0; i < slideCount; i++) {
        // Scroll to the slide
        await page.evaluate((idx) => {
            const slides = document.querySelectorAll('.slide');
            slides[idx].scrollIntoView({ behavior: 'instant', block: 'start' });
        }, i);

        // Wait for scroll + animations to settle
        await page.waitForTimeout(700);

        const idx = String(i + 1).padStart(3, '0');
        await page.screenshot({ path: `${outDir}/slide_${idx}.png` });
        console.error(`  Captured slide ${i + 1}`);
    }

    console.log(JSON.stringify({ captured: slideCount }));
    await browser.close();
    server.close();
})();
JSEOF
